SOURCES={key:dict(id='v9b-'+key,title=zh,titleEn=en,publisher=publisher,url=url,scope=zhscope,scopeEn=enscope,accessedAt='2026-10-14',sourceType='primary',category='packaging',imageReuse='link-only; no image republication permission implied') for key,zh,en,publisher,url,zhscope,enscope in SOURCE_ROWS}

def pair(s):
    return s.split('~',1)

def build_course(cid,cfg):
    c=copy.deepcopy(CAT[cid]);focusz,focuse=pair(cfg['focus']); bz,be=pair(cfg['boundary']);ez,ee=pair(cfg['example'])
    stagepairs=[pair(v) for v in cfg['stages'].split('|')];assert len(stagepairs)==4
    sid=['v9b-'+r for r in cfg['refs']]
    c.update(category='packaging',kind='course',status='guided',contentStatus='reviewable-educational-curriculum',curriculumVersion=9,depth=4,stepCount=24,estimatedMinutes=720,simulationOnly=True,languageCoverage=['zh-TW','en'],sourceIds=sid,
      summary=f'以四階段、24 步深入{focusz}；每個技術單元分為建模與證據驗證，包含可重算的教學算例、失效辨識及相關工法。',
      summaryEn=f'Four stages and 24 steps examine {focuse.lower()}. Each technical unit separates modeling from evidence validation, with reproducible teaching examples, failure diagnosis and related methods.',
      scope='公開資料支持的原理與工程判讀課；24 步是學習拆解，不是工廠完整 SOP。數值均為明示假設的教學例；實際材料、設備、驗收門檻須依專案規格。'+bz,
      scopeEn='A principles and engineering-interpretation course grounded in public material. The 24 steps are an educational decomposition, not a complete factory SOP. Numbers are labeled hypothetical; actual materials, equipment and acceptance limits require project specifications. '+be,
      diagram=dict(type='photonics' if int(cid[1:])>=151 else 'packaging',labels=[x[0] for x in stagepairs],labelsEn=[x[1] for x in stagepairs],original=True,notToScale=True),stages=[])
    wrong=[pair(x) for x in cfg['wrong'].split('|')]; assert len(wrong)==2
    for st,(sz,se) in enumerate(stagepairs):
      stage=dict(id=f'{cid}-v9-stage{st+1:02}',order=st+1,title=sz,titleEn=se,
       description=f'本階段處理{sz}：依序完成三個技術單元的模型與獨立驗證，將物理主張連到可觀察資料。',
       descriptionEn=f'Address {se.lower()} through three technical units, each with a model and independent verification linking physical claims to observable evidence.',steps=[])
      for u in range(st*3,st*3+3):
       (tz,te),(pz,pe),(vz,ve)=cfg['units'][u]
       for mode in range(2):
        no=u*2+mode+1;stepid=f'{cid}-v9-{no:02}'
        k=[dict(id=stepid+'-k1',title=tz+'：機制',titleEn=te+': mechanism',text=pz,textEn=pe,sourceIds=sid),dict(id=stepid+'-k2',title=tz+'：證據與判讀',titleEn=te+': evidence and interpretation',text=vz+' 記錄原始觀察和推論之間的區別。',textEn=ve+' Keep raw observations distinct from inference.',sourceIds=sid)]
        calc=any(x in tz+vz for x in ['重算','驗算','算例','範例'])
        if calc:
         k.append(dict(id=stepid+'-k3',title='自訂算例與模型界限',titleEn='Hypothetical worked example and model boundary',text=ez+' '+bz,textEn=ee+' '+be,sourceIds=sid))
        title=tz if not mode else tz+'：反證與驗收'
        titleEn=te if not mode else te+': challenge and acceptance'
        if mode==0:
         objective=f'建立「{tz}」的可檢驗工程模型，說明：{pz}'
         objectiveEn=f'Build a testable engineering model for {te.lower()}: {pe}'
         instruction=f'先在工程筆記畫出本單元的系統邊界、材料或訊號路徑。{vz} 把操作前後的預測分開記錄，標示量綱、固定條件與一項待量測輸入；引用原始來源的適用條件，不把示意圖當實測。'
         instructionEn=f'Sketch this unit’s system boundary and material or signal path. {ve} Record before/after predictions separately, with dimensions, controlled conditions and one input requiring measurement. Respect source validity conditions and distinguish a schematic from measured evidence.'
         check=f'交付「{tz}」模型與比較圖，至少包含本步指定的操作、預測方向、量測單位及未驗證假設。'
         checkEn=f'Submit the model and comparison for {te.lower()}, including the specified action, predicted direction, units and an unvalidated assumption.'
         correct=(pz,pe)
        else:
         objective=f'以獨立證據檢驗「{tz}」的模型，辨別真實效應與量測或模型誤差。'
         objectiveEn=f'Test the {te.lower()} model with independent evidence and separate physical effects from measurement or model error.'
         instruction=f'沿用上一步模型，但先寫下什麼結果會推翻它。{vz} 加入一組對照或重複量測，改變一個會造成混淆的條件，將觀察分為支持、矛盾及仍不足。若只有模擬資料，清楚標成模擬，並指定下一項實物驗證。'
         instructionEn=f'Use the previous model, first specifying what result would refute it. {ve} Add a control or repeated measurement, vary one confounder, and classify observations as supporting, conflicting or insufficient. Label simulated data explicitly and specify the next physical validation.'
         check=f'交付「{tz}」的驗收紀錄：包含指定觀察、誤差來源、能支持的結論與一項應暫緩放行的結果。'
         checkEn=f'Submit acceptance evidence for {te.lower()}: the specified observation, error sources, supported conclusion and one hold condition.'
         correct=(vz,ve)
        if calc:
         instruction+='\n\n'+ez;instructionEn+='\n\n'+ee
        opts=[correct,wrong[0],wrong[1]];ans=no%3;opts=opts[-ans:]+opts[:-ans] if ans else opts
        step=dict(id=stepid,order=no,sequence=no,estimatedMinutes=30,simulationOnly=True,sourceIds=sid,prerequisiteIds=[] if no==1 else [f'{cid}-v9-{no-1:02}'],title=title,titleEn=titleEn,objective=objective,objectiveEn=objectiveEn,instruction=instruction,instructionEn=instructionEn,
         observation=f'觀察焦點：{vz} 只有在控制條件一致且差異大於量測不確定度時，才把差異歸於所討論的機制。',
         observationEn=f'Observation focus: {ve} Attribute differences to the mechanism only with matched controls and differences distinguishable from measurement uncertainty.',
         failure=f'需排除的錯判：{wrong[mode][0]}。本步先檢查「{tz}」的證據是否真的支持機制；若不支持，回到{pz}所指出的物理限制。',
         failureEn=f'Misinterpretation to reject: {wrong[mode][1]}. First check whether evidence for {te.lower()} actually supports the mechanism. If not, revisit the physical constraint: {pe}',
         check=check,checkEn=checkEn,knowledge=k,
         quiz=dict(question=f'在「{title}」中，哪個處理方式或主張有物理依據？',questionEn=f'Which approach or claim is physically justified for {titleEn.lower()}?',options=[x[0] for x in opts],optionsEn=[x[1] for x in opts],answer=ans,explanation=pz+' '+vz,explanationEn=pe+' '+ve))
        stage['steps'].append(step)
      c['stages'].append(stage)
    return c


def build_related(cid,cfg):
    rel=[]
    for rid,tr,df in cfg['related']:
        tz,te=pair(tr);dz,de=pair(df);target=CAT[rid];first=cfg['units'][0][0];focus=pair(cfg['focus'])
        rel.append(dict(id=rid,title=target['title'],titleEn=target['titleEn'],why=tz,whyEn=te,transfer=tz,transferEn=te,difference=dz,differenceEn=de,
          practice=[f'畫出「{CAT[cid]["title"]}」與「{target["title"]}」的材料、能量或資料交接。',f'以「{first[0]}」為比較起點，指出兩課共享的守恆或量測原理。',f'提出一個會使「{tz}」失效的邊界條件，並安排驗證。'],
          practiceEn=[f'Draw the material, energy or data handoff between {CAT[cid]["titleEn"]} and {target["titleEn"]}.',f'Use {first[1].lower()} to identify a shared conservation or measurement principle.',f'State and test one boundary that would invalidate this transfer: {te}'],referenceUrls=[SOURCES[r]['url'] for r in cfg['refs']]))
    return dict(courseId=cid,overview='相似工法的重點是可轉移的物理與證據；下列比較保留各自不同的材料和模型邊界。',overviewEn='Related methods share transferable physics and evidence while retaining distinct materials and model boundaries.',related=rel,references=[{k:s[k] for k in ['title','titleEn','publisher','url']} for s in (SOURCES[r] for r in cfg['refs'])])


def build_place(cid,cfg):
    focusz,focuse=pair(cfg['focus'])
    return dict(courseId=cid,place=dict(name='imec 魯汶園區（公開研究代表點）',nameEn='imec Leuven campus (public research reference)',city='魯汶',cityEn='Leuven',country='比利時',countryEn='Belgium',lat=50.864928,lng=4.679817,mapQuery='imec 1, Kapeldreef 75, 3001 Leuven, Belgium',address='imec 1, Kapeldreef 75, 3001 Leuven, Belgium',addressEn='imec 1, Kapeldreef 75, 3001 Leuven, Belgium',coordinateScope='官方會議場址公布的園區代表座標；本課採用多國公開來源，不主張每一技術在此發明或量產，也不是設備位置。',coordinateScopeEn='Campus reference coordinates published for an official event. The course draws on international sources; this is not a claim of local invention, production or equipment location.'),
     summary=f'本課以{focusz}連結材料、模型與驗證。地圖採 imec 公開研究園區作為跨領域整合的代表點；製造、量測及可靠度資料則分別引用材料廠、工具商與研究機構。這個位置提供研究脈絡，不把全球供應鏈誤縮成一處工廠。',
     summaryEn=f'This course connects materials, models and validation through {focuse.lower()}. Imec’s public campus is a reference for interdisciplinary integration; manufacturing, metrology and reliability sources also come from vendors and research institutions. The map provides research context rather than reducing the global supply chain to one factory.',
     history=[dict(year='1984',title='合作研究中心在魯汶成立',titleEn='A collaborative research center starts in Leuven',text='imec 官方歷史記錄其成立背景；共同研究模式使材料、元件和系統問題能在同一研究環境連結。',textEn='Imec’s official history records its establishment; collaborative research connects materials, devices and systems in one research environment.',sourceIds=['v9b-imec-history']),dict(year='2019',title='微流體散熱連結晶片與系統',titleEn='Microfluidic cooling connects chips and systems',text='imec 公開介紹矽微流道研究，說明晶片性能需與散熱及封裝一起思考；此為研究展示，不是所有課程的量產規格。',textEn='Imec publicly described silicon microchannel research, illustrating the need to consider chip performance together with cooling and packaging. This is a research demonstration, not a production specification for every course.',sourceIds=['v9b-imec-cooling'])],
     connection='將地圖視為研究交流的定位點，再依每個來源了解不同機構在材料、設備、量測與系統驗證上的分工。',connectionEn='Use the map as a research reference, then trace each source’s role in materials, equipment, metrology and system validation.',sourceIds=['v9b-imec-venue','v9b-imec-history','v9b-imec-cooling'],references=[{k:SOURCES[r][k] for k in ['title','titleEn','publisher','url']} for r in ['imec-venue','imec-history','imec-cooling']])


def main():
    assert set(DATA)=={f'a{x}' for x in range(136,156)}
    out=dict(courses=[build_course(cid,cfg) for cid,cfg in DATA.items()],sources=list(SOURCES.values()),places=[build_place(cid,cfg) for cid,cfg in DATA.items()],related=[build_related(cid,cfg) for cid,cfg in DATA.items()])
    for c in out['courses']:
      assert len(c['stages'])==4 and all(len(s['steps'])==6 for s in c['stages'])
      steps=[x for s in c['stages'] for x in s['steps']];assert len(steps)==24
      for s in steps:
       assert len(s['knowledge'])>=2
       for k in ['title','objective','instruction','observation','failure','check']:
        assert s[k] and s[k+'En']
       q=s['quiz'];assert len(q['options'])==3 and len(q['optionsEn'])==3 and 0<=q['answer']<3
    dest=Path(__file__).with_name('group_b_core.json');dest.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps(dict(path=str(dest),courses=len(out['courses']),steps=sum(c['stepCount'] for c in out['courses']),knowledgePoints=sum(len(s['knowledge']) for c in out['courses'] for st in c['stages'] for s in st['steps']),sources=len(out['sources']),related=sum(len(x['related']) for x in out['related'])),ensure_ascii=False))
if __name__=='__main__':main()
